import { JSX, mergeProps, ParentComponent, Show } from "solid-js";

import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

export enum SafezoneMode {
	None,
	Vertical,
	Horizontal,
	Full,
}

export interface FrameProps {
	// Default: None
	safezoneMode?: SafezoneMode;

	/* Default: -z-1 fullscreen pt-14 px-10 pb-10 */
	class?: string;
	contentClass?: string;

	/* Default: mt-8 */
	filigreeClass?: string;

	borderClass?: string;
	style?: JSX.CSSProperties;
}

interface FrameBaseProps extends FrameProps {
	frameClass: string;
	showFiligrees: boolean;
}

function safezoneModeToClass(safezoneMode: SafezoneMode) {
	switch (safezoneMode) {
		case SafezoneMode.Full:
			return "fullscreen-outside-safezone";

		case SafezoneMode.Horizontal:
			return "fullscreen-outside-safezone-x";

		case SafezoneMode.Vertical:
			return "fullscreen-outside-safezone-y";

		default:
			return "";
	}
}

const FrameBaseComponent: ParentComponent<FrameBaseProps> = (props) => {
	const mergedProps = mergeProps(props, {
		class: "absolute w-full h-full flex justify-center",
		filigreeClass: "mt-8",
		safezoneMode: SafezoneMode.None,
	});

	return (
		<div class={`z-0 ${mergedProps.class ?? ""}`}>
			<div
				class={`-z-1 relative flex flex-col flex-auto pt-14 px-10 pb-10  ${props.frameClass} ${safezoneModeToClass(mergedProps.safezoneMode)} ${props.contentClass ?? ""}`}
				style={props.style}
			>
				<Show when={props.showFiligrees}>
					<div
						class={`absolute top-0 left-4 bottom-0 h-1\\/2 w-64 ${mergedProps.filigreeClass ?? ""} img-frame-filigree pointer-events-none`}
					/>
					<div
						class={`absolute top-0 right-4 bottom-0 h-1\\/2 w-64 ${mergedProps.filigreeClass ?? ""} rotate-y-180 img-frame-filigree pointer-events-none`}
					/>
				</Show>
				<Show when={props.borderClass}>
					<div class="flex absolute self-stretch w-full">
						<div class={props.borderClass} />
					</div>
				</Show>
				{props.children}
			</div>
		</div>
	);
};

const FrameF1Component: ParentComponent<FrameProps> = (props) => {
	return (
		<FrameBaseComponent
			{...props}
			frameClass="img-frame-f1"
			showFiligrees={true}
		/>
	);
};

const FrameF2Component: ParentComponent<FrameProps> = (props) => {
	return (
		<FrameBaseComponent
			{...props}
			frameClass="img-frame-f2"
			showFiligrees={true}
		/>
	);
};

const FrameSimpleComponent: ParentComponent<FrameProps> = (props) => {
	return (
		<FrameBaseComponent
			{...props}
			frameClass="img-frame-f2"
			showFiligrees={false}
		/>
	);
};

const FrameModalComponent: ParentComponent<FrameProps> = (props) => {
	return (
		<FrameBaseComponent
			{...props}
			frameClass="img-modal-frame"
			showFiligrees={false}
		/>
	);
};

export const Frame = {
	F1: ComponentRegistry.register("Frame.F1", FrameF1Component),
	F2: ComponentRegistry.register("Frame.F2", FrameF2Component),
	Simple: ComponentRegistry.register("Frame.Simple", FrameSimpleComponent),
	Modal: ComponentRegistry.register("Frame.Modal", FrameModalComponent),
};
